import{_ as a,H as l,f as t,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"02 | 挑战与趋势：云原生时代JVM的演进之路","description":"","frontmatter":{},"headers":[{"level":2,"title":"趋势的力量","slug":"趋势的力量","link":"#趋势的力量","children":[]},{"level":2,"title":"云原生时代","slug":"云原生时代","link":"#云原生时代","children":[{"level":3,"title":"云原生时代的开发趋势","slug":"云原生时代的开发趋势","link":"#云原生时代的开发趋势","children":[]},{"level":3,"title":"无服务器","slug":"无服务器","link":"#无服务器","children":[]},{"level":3,"title":"容器化","slug":"容器化","link":"#容器化","children":[]},{"level":3,"title":"基础设施：Kubernetes","slug":"基础设施-kubernetes","link":"#基础设施-kubernetes","children":[]},{"level":3,"title":"分布式、弹性伸缩、微服务架构","slug":"分布式、弹性伸缩、微服务架构","link":"#分布式、弹性伸缩、微服务架构","children":[]}]},{"level":2,"title":"云时代 JVM 的挑战","slug":"云时代-jvm-的挑战","link":"#云时代-jvm-的挑战","children":[{"level":3,"title":"启动时间","slug":"启动时间","link":"#启动时间","children":[]},{"level":3,"title":"启动性能","slug":"启动性能","link":"#启动性能","children":[]},{"level":3,"title":"内存占用","slug":"内存占用","link":"#内存占用","children":[]},{"level":3,"title":"面向对象","slug":"面向对象","link":"#面向对象","children":[]}]},{"level":2,"title":"JVM 的发展趋势","slug":"jvm-的发展趋势","link":"#jvm-的发展趋势","children":[{"level":3,"title":"拥抱容器化","slug":"拥抱容器化","link":"#拥抱容器化","children":[]},{"level":3,"title":"容器亲和性","slug":"容器亲和性","link":"#容器亲和性","children":[]},{"level":3,"title":"AOT 原生镜像编译","slug":"aot-原生镜像编译","link":"#aot-原生镜像编译","children":[]},{"level":3,"title":"函数式支持增强","slug":"函数式支持增强","link":"#函数式支持增强","children":[]},{"level":3,"title":"GraalVM","slug":"graalvm","link":"#graalvm","children":[]},{"level":3,"title":"版本快速更迭","slug":"版本快速更迭","link":"#版本快速更迭","children":[]},{"level":3,"title":"JVM 家族","slug":"jvm-家族","link":"#jvm-家族","children":[]}]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"点亮你的知识框架图","slug":"点亮你的知识框架图","link":"#点亮你的知识框架图","children":[]}],"relativePath":"云时代的JVM原理与实战/02｜挑战与趋势：云原生时代JVM的演进之路.md","filePath":"云时代的JVM原理与实战/02｜挑战与趋势：云原生时代JVM的演进之路.md","lastUpdated":1795541359000}'),r={name:"云时代的JVM原理与实战/02｜挑战与趋势：云原生时代JVM的演进之路.md"};function n(s,e,h,o,p,E){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_02-挑战与趋势-云原生时代jvm的演进之路" tabindex="-1">02 | 挑战与趋势：云原生时代JVM的演进之路 <a class="header-anchor" href="#_02-挑战与趋势-云原生时代jvm的演进之路" aria-label="Permalink to &quot;02 | 挑战与趋势：云原生时代JVM的演进之路&quot;">​</a></h1><p>你好，我是康杨。</p><p>今天我想和你聊聊关于趋势的事儿。我们一起来看看 JVM 在云时代面临的挑战，还有它是如何应对的，以此来推断出我们应该做哪些准备，来更从容地应对这个快速变化的时代。</p><h2 id="趋势的力量" tabindex="-1">趋势的力量 <a class="header-anchor" href="#趋势的力量" aria-label="Permalink to &quot;趋势的力量&quot;">​</a></h2><p>还记得 2004 年，我刚开始第一份编程工作的时候，那时候还是 Win32 的天下，我的老板是个台湾人，他是 Delphi 的拥趸，经常挂在嘴边的一句话就是“Delphi 永垂不朽”，但是现在听说过Delphi 的人，想必寥寥无几。</p><p>2008 年，Facebook 刚刚兴起，social game 火遍全球，国内做社交网站或者社交游戏的互联网公司如雨后春笋般涌现，做 ActionScript 3 的工程师，工资水涨船高，但现在基本都转型了。</p><p>其实不光是编程语言，NOKIA 与柯达的故事，也都印证了那句话“其兴也勃焉，其亡也忽焉”，而这背后就是趋势的力量。所以在学习任何语言或技术之前，如果能对趋势有一定的预判，将很大程度上避免自身陷入窘境。</p><h2 id="云原生时代" tabindex="-1">云原生时代 <a class="header-anchor" href="#云原生时代" aria-label="Permalink to &quot;云原生时代&quot;">​</a></h2><p>几年前“是否上云”还是社会上的热门话题，但当时间来到 2023 年，不管是互联网大厂还是传统的金融机构，都早已完成了基础设施的建设和应用上云的转化。</p><p>而这不过是印证了 Berkeley 在 2009 年发布的那篇论文《Above the Clouds : A BerkeleyView of Cloud Computing 》，这也让我们不得不认真审视 Berkeley 的另一篇论文《CloudProgramming Simplified : A Berkeley View on Serverless Computing 》 ，这篇论文预言了云原生时代的到来。</p><h3 id="云原生时代的开发趋势" tabindex="-1">云原生时代的开发趋势 <a class="header-anchor" href="#云原生时代的开发趋势" aria-label="Permalink to &quot;云原生时代的开发趋势&quot;">​</a></h3><p>云原生时代的开发趋势主要集中在无服务器（Serverless）、容器化、Kubernetes、分布式等几个方面。</p><h3 id="无服务器" tabindex="-1">无服务器 <a class="header-anchor" href="#无服务器" aria-label="Permalink to &quot;无服务器&quot;">​</a></h3><p>云原生时代弱化了服务器的概念。我们可以这样理解，在云原生环境中，我们更侧重于解决问题本身，而不是关注解决问题的具体步骤或工具，也就是服务器。在这种情况下，解决问题的方法会变得越来越自然，不需要过多地关注具体的工具或步骤，就像是没有服务器存在一样。这就是所谓的 Serverless 的概念。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/1.png" alt=""></a></p><h3 id="容器化" tabindex="-1">容器化 <a class="header-anchor" href="#容器化" aria-label="Permalink to &quot;容器化&quot;">​</a></h3><p>区别于 JVM 实现的语言层虚拟化，容器采用的是操作系统层虚拟化解决方案，可以为每个容器分配资源，并允许在容器内运行各种应用程序和进程，而不仅仅是 Java 应用程序。这给了容器许多优势，比如环境一致性，无论容器在什么地方运行，它的内部环境都是一致的，容器与容器之间互相不影响。此外容器还有资源隔离、开发效率和运维效率的提高、可扩展性和可移植性等特性。</p><h3 id="基础设施-kubernetes" tabindex="-1">基础设施：Kubernetes <a class="header-anchor" href="#基础设施-kubernetes" aria-label="Permalink to &quot;基础设施：Kubernetes&quot;">​</a></h3><p>Kubernetes 作为云时代的基础设施已经得到了时代的认可，它在容器化部署和资源管理等方面展现的自动化、弹性伸缩和容错能力已经成为了现在架构的基础。</p><h3 id="分布式、弹性伸缩、微服务架构" tabindex="-1">分布式、弹性伸缩、微服务架构 <a class="header-anchor" href="#分布式、弹性伸缩、微服务架构" aria-label="Permalink to &quot;分布式、弹性伸缩、微服务架构&quot;">​</a></h3><p>云时代的系统开发需要支持大规模的分布式计算和存储，能有效应对海量数据处理和分析的需要。云计算平台提供了弹性的资源分配机制，应用可以根据业务需求自动伸缩计算资源。系统开发通常采用微服务架构，把系统分解成一组小型、独立的服务，每个服务都在自己的进程中运行，各自独立部署。</p><h2 id="云时代-jvm-的挑战" tabindex="-1">云时代 JVM 的挑战 <a class="header-anchor" href="#云时代-jvm-的挑战" aria-label="Permalink to &quot;云时代 JVM 的挑战&quot;">​</a></h2><p>首先让我们一起回顾下 Java 那些耳熟能详的特点：everything is object、平台无关性、垃圾回收机制、完善的生态体系。这些曾经让 Java 引以为傲的优势，当云原生时代来临的时候，正在成为牵绊它前行的阻力，云原生时代 Java 的各种缺陷逐渐凸显。</p><h3 id="启动时间" tabindex="-1">启动时间 <a class="header-anchor" href="#启动时间" aria-label="Permalink to &quot;启动时间&quot;">​</a></h3><p>首当其冲的就是启动时间，我们都知道 JVM 是个慢热型选手。它在启动时需要加载很多类文件，而如果你的应用需要在启动时候建立各种长链接，那启动时间基本上要以分钟来计算了。</p><h3 id="启动性能" tabindex="-1">启动性能 <a class="header-anchor" href="#启动性能" aria-label="Permalink to &quot;启动性能&quot;">​</a></h3><p>其次是启动性能，由于 JVM 需要在系统运行一段时间后才能逐步由解释执行转化为解释执行+ 编译执行，这也意味着 JVM 的系统需要经过一段时间的预热才能达到性能巅峰。这就像冬天的燃油车一样，必须先把发动机充分预热，才能真正上路。</p><h3 id="内存占用" tabindex="-1">内存占用 <a class="header-anchor" href="#内存占用" aria-label="Permalink to &quot;内存占用&quot;">​</a></h3><p>相较于在运行态只包含机器码和垃圾回收器的 Go 语言，JVM 的运行态即使只进行简单的加减乘除运算，也需要包含一个完整的解释器、一个即时编译器、一个垃圾回收器，在这个以快著称的云时代，显得有点太重了。</p><h3 id="面向对象" tabindex="-1">面向对象 <a class="header-anchor" href="#面向对象" aria-label="Permalink to &quot;面向对象&quot;">​</a></h3><p>曾经 Java 语言就是面向对象的代名词，Java 的那句 Slogan：everything is object，即使没有使用过 Java 语言的人也都听说过。但是你是否思考过，面向对象是否是唯一的选择？everything is object 的成本是什么？</p><p>一个 32 位 Integer 对象在内存中的空间占用如下：</p><ul><li><p>对象头部：Header，通常占据 8 个字节。用来存储对象的元数据信息，比如对象的类型指针、锁状态等。</p></li><li><p>实际存储的整数值：占据 4 个字节，用来存储 32 位整数的值。</p></li></ul><p>因此，一个 32 位的 Integer 对象在运行时会占用 12 字节的内存空间。在实际情况中，JVM为了对齐内存访问会把结构体的大小向上取整到 8 的倍数，所以通常会占用 16 字节的内存空间。这还不包括内存分配、垃圾回收、并发调用等耗费的其他资源成本。</p><p>那面向对象是什么，是不是必需的呢？其实面向对象只是一种抽象客观世界的方式，随着“优先使用对象组合而非类继承”逐步被大家接受，面向对象的优势正在慢慢弱化。作为新一代编程语言的代表，Go 和 Rust 其实都摒弃了面向对象的概念，并快速地发展着。这也从侧面证明面向对象并不是必需的选择。所以如何在云时代平衡面向对象的优势和成本，也是 Java 要面临的挑战之一。</p><h2 id="jvm-的发展趋势" tabindex="-1">JVM 的发展趋势 <a class="header-anchor" href="#jvm-的发展趋势" aria-label="Permalink to &quot;JVM 的发展趋势&quot;">​</a></h2><p>在这个确定的云时代，我们似乎看到一个不确定的 JVM 的未来。但是作为一个发展了 28 年有着庞大生态支撑的王者，JVM 显然不会坐以待毙，下面我们就来看看 JVM 的应对之道。</p><h3 id="拥抱容器化" tabindex="-1">拥抱容器化 <a class="header-anchor" href="#拥抱容器化" aria-label="Permalink to &quot;拥抱容器化&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/2.png" alt=""></a></p><p>New Relic 的数据显示，目前已经有 70% 的 Java 应用是运行在容器中的。为了更好地支持容器化，JVM 逐步放弃了自己原本的平台无关的解决方案，转而拥抱容器化。</p><h3 id="容器亲和性" tabindex="-1">容器亲和性 <a class="header-anchor" href="#容器亲和性" aria-label="Permalink to &quot;容器亲和性&quot;">​</a></h3><p>在 JDK 8u131 版本之前，JVM 不具备容器识别能力。这对于已经上云，但还在使用 JDK 8 的Java 应用来说，存在致命的风险。因为 JVM 会基于宿主机的物理内存来设置堆内存的最大值，而不是基于容器的内存限制，从而导致 JVM 试图使用超出容器限制内存的情况出现，进而被操作系统杀掉，CPU 的使用也存在同样的问题。</p><p>在 JDK 11、JDK 17 中，JVM 增加了对容器环境的识别能力。JVM 会读取来自操作系统（Docker）和容器管理系统（Kubernetes）提供的信息，来了解它所在的容器的资源限制。JVM 会把这些信息用于堆内存、JIT 编译器的管理中，并且这些新增的功能是默认开启的，无需任何特殊的配置。</p><h3 id="aot-原生镜像编译" tabindex="-1">AOT 原生镜像编译 <a class="header-anchor" href="#aot-原生镜像编译" aria-label="Permalink to &quot;AOT 原生镜像编译&quot;">​</a></h3><p>从 JDK 9 开始，JVM 支持 AOT（Ahead-Of-Time）编译技术，并在 JDK 11、17 版本中持续增强。AOT 指的是在 JVM 运行之前把代码编译成本地机器码的技术。通过提前将 Java 应用程序编译为即时启动的本地二进制文件，JVM 在无需预热的情况下就可以提供峰值性能。</p><p>同时，即时编译会产生大量的中间编译代码和相关的数据结构，导致程序占用更多的内存，而AOT 编译可以在编译时根据具体平台进行优化，减少了这些额外的开销，节省了内存空间。</p><h3 id="函数式支持增强" tabindex="-1">函数式支持增强 <a class="header-anchor" href="#函数式支持增强" aria-label="Permalink to &quot;函数式支持增强&quot;">​</a></h3><p>JVM 持续加强对函数式的支持，参照 Go 语言，通过逃逸分析、栈上分配等操作持续提升栈的利用效率。基于函数式编程风格更加强调不可变性和无副作用的特性，产生的垃圾更少。此外，JVM 还引入了 Epsilon 垃圾收集器，这是一个不执行任何垃圾收集的收集器。当应用程序不需要自动内存管理或者为了测试和性能调整而需要关闭垃圾收集时使用。</p><p>JDK 11 对 Lambda 表达式进行了改进，Lambda 参数可利用 var 关键字声明类型，使Lambda 表达式的代码更加简洁。这些改进和新增特性都彰显出 JVM 在加强函数式编程方面做出的努力。</p><h3 id="graalvm" tabindex="-1">GraalVM <a class="header-anchor" href="#graalvm" aria-label="Permalink to &quot;GraalVM&quot;">​</a></h3><p>GraalVM 是 Oracle Labs 于 2018 年 4 月首次公开发布的高性能 JDK 发行版，它的目标是提升在 JVM 上运行的程序的性能，包括 Java、Scala、Groovy、Kotlin 等多种语言。GraalVM的主要亮点在于其全新的即时（Just-In-Time）编译器，该编译器采用最新的编译器技术和研究成果，对 Java 的程序性能进行了大幅提升。</p><p>最引人注目的一点是，GraalVM 支持 AOT 编译，这意味着它可以将 Java 程序编译成本地可执行文件，极大地减少了启动时间和内存占用，更适应在云原生环境下运行。2019 年 5 月，发布了 GraalVM 的第一个正式版本，也就是 Release 版本。</p><p>GraalVM 为开发者提供了一种新的、高效的、可扩展的运行环境，使不同编程语言的运行性能有了大幅提升。</p><h3 id="版本快速更迭" tabindex="-1">版本快速更迭 <a class="header-anchor" href="#版本快速更迭" aria-label="Permalink to &quot;版本快速更迭&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/3.png" alt=""></a></p><p>上面这张图是 New Reliic 最新发布的《2023 年 Java 生态系统现状》的数据，我们看到Java 7 马上要退出历史的舞台，Java 8 的比例快速下降，Java 11 已经连续两年高居各版本之首。Java 17 的采用率在过去一年内更是实现了 430% 的增长。而作为 Java 生态支持云原生的风向标 Spring 6 和 Spring Boot 3 支持的 JDK 最低版本就是 Java 17。这也意味着以JDK 17 为基础的 Java 云原生生态即将来临。</p><h3 id="jvm-家族" tabindex="-1">JVM 家族 <a class="header-anchor" href="#jvm-家族" aria-label="Permalink to &quot;JVM 家族&quot;">​</a></h3><p>以前当我们看到 Java 的时候，肯定会想到 SUN 或者今天的 Oracle，安装 JDK 的时候也会去Oracle 的官网下载。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/4.png" alt=""></a></p><p>可是在 New Reliic 的报告中，我们发现亚马逊才是现在最受欢迎的 JDK 供应商。因为 OracleJDK 的商业收费政策、Open JDK 的蓬勃发展，再加上现在越来越热的信息技术应用创新，很多一线大厂开始打造自己的 JDK 版本。其中就包括阿里巴巴在 2019 年 3 月开源的Dragonwell，腾讯 2019 年 11 月开源的 Kona，以及华为在 2020 年 9 月发布的毕昇。今天当你开始在生产环境中使用 Java 的时候，选择哪个 JDK 供应商已经成为了一个需要考虑的选项。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>JVM 经历了过去辉煌的 28 年，但在已经来临的云时代，原有的优势面临着新的挑战，为了适应云时代高性能、高可扩展性、高可靠性和高安全性的要求，JVM 也在努力地进行自我革新。</p><p>总的来说，JVM 的发展方向主要包括 3 个方面。</p><ol><li><p>首先是性能优化，通过提高性能和资源利用率来适应云原生时代的需求。其中最主要的技术是 AOT 编译器和 JIT 编译器的结合，以及 JVM 的内存管理和垃圾回收机制的优化。</p></li><li><p>其次是对容器化的支持，通过支持容器化和新的微服务架构以适应云原生时代的需求。其中最主要的技术是 JVM 的镜像化和容器化以及对容器化环境的适配。</p></li><li><p>最后是安全性和可靠性的提升，通过持续提高安全性和可靠性来适应新时代的要求。</p></li></ol><p>我们也看到 JVM 版本的快速迭代和不断出现的 JVM 提供商，了解整个 JVM 的生态，对我们日后学习以及在生产中推进 JVM 的持续迭代有重要的意义。</p><p>参考资料：《2023 年 Java 生态系统现状》</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>云原生时代，JVM 的挑战主要有哪些？它是如何应对的？</p><p>欢迎你把你对这节课的思考分享到评论区，和我一起讨论，也欢迎你把这节课分享给需要的朋友，我们下节课再见！</p><h2 id="点亮你的知识框架图" tabindex="-1">点亮你的知识框架图 <a class="header-anchor" href="#点亮你的知识框架图" aria-label="Permalink to &quot;点亮你的知识框架图&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/02/5.jpeg" alt=""></a></p>',71)])])}const d=a(r,[["render",n]]);export{u as __pageData,d as default};
